CREATE TABLE IF NOT EXISTS announcements (id VARCHAR(255) PRIMARY KEY, title VARCHAR(255), content TEXT, type VARCHAR(50), sender_id VARCHAR(255), target_scope VARCHAR(255), published_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS prayer_feed (id VARCHAR(255) PRIMARY KEY, user_id VARCHAR(255), request TEXT, is_anonymous BOOLEAN DEFAULT FALSE, prayer_count INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_templates (id VARCHAR(255) PRIMARY KEY, name VARCHAR(255), title VARCHAR(255), body TEXT, channel VARCHAR(50));
